mapper.select:
SELECT 
  FROM tc_ui_auth_session
 WHERE user_pk = #{userPk}
 ORDER BY issued_at DESC, token ASC
 LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE tc_ui_auth_session
   SET revoked = true
 WHERE token = #{token}

UPDATE tc_ui_auth_session
   SET last_seen_at = #{lastSeenAt, typeHandler=com.nori.tc.db.mybatis.common.typehandler.OffsetDateTimeTypeHandler}
 WHERE token = #{token}
